        abstract context: GatewayErrorContext option with get, set
        abstract raw: obj option with get, set
        abstract cause: obj option with get, set
        [<ParamObject; Emit("$0")>]
        static member Create (?recoverable: bool, ?status: float, ?context: GatewayErrorContext, ?raw: obj, ?cause: obj) : Opts = jsNative

