module WorkersAITranscriptionModel =
    [<Interface>]
    type Config =
        abstract provider: string with get, set
        abstract binding: obj with get, set
        abstract gateway: obj option with get, set
        /// <summary>
        /// Whether the binding is a real <c>env.AI</c> binding (true) or a REST shim (false).
        /// Nova-3 uses different upload paths depending on this.
        /// </summary>
        abstract isBinding: bool with get, set
        /// <summary>
        /// REST credentials, only set when <c>isBinding</c> is false.
        /// Needed for Nova-3 which requires binary upload, bypassing the JSON-based REST shim.
        /// </summary>
        abstract credentials: CreateRunConfig option with get, set
        [<ParamObject; Emit("$0")>]
        static member Create (provider: string, binding: obj, isBinding: bool, ?gateway: obj, ?credentials: CreateRunConfig) : Config = jsNative

type GatewayDelegateErrorConstructor =
    /// <summary>
    /// Indicates whether the argument provided is a built-in Error instance or not.
    /// </summary>
    abstract isError: error: obj -> bool
    [<EmitConstructor>]
    abstract Create: kind: GatewayDelegateErrorKind * message: string * ?cause: obj -> GatewayDelegateError

/// <summary>
/// A single dispatch failure through AI Gateway (run or gateway path).
/// </summary>
type WorkersAIGatewayErrorConstructor =
    /// <summary>
    /// Classify an arbitrary thrown value. Understands AI SDK <c>APICallError</c>
    /// (reads <c>statusCode</c> / <c>responseBody</c> / <c>isRetryable</c>); falls back to a
    /// recoverable <c>gateway-error</c> for transport/connection failures so a fallback
    /// chain keeps trying.
    /// </summary>
    abstract fromUnknown: e: obj -> WorkersAIGatewayError
    /// <summary>
    /// Build from an HTTP <c>Response</c> (reads the body for the envelope).
    /// </summary>
    abstract fromResponse: resp: obj * ?context: GatewayErrorContext -> JS.Promise<WorkersAIGatewayError>
    /// <summary>
    /// Indicates whether the argument provided is a built-in Error instance or not.
    /// </summary>
    abstract isError: error: obj -> bool
    /// <summary>
    /// A single dispatch failure through AI Gateway (run or gateway path).
    /// </summary>
    [<EmitConstructor>]
    abstract Create: code: GatewayErrorCode * message: string * ?opts: WorkersAIGatewayError.Opts -> WorkersAIGatewayError

/// <summary>
/// Every model in a client-side fallback chain failed.
/// </summary>
type WorkersAIFallbackErrorConstructor =
    /// <summary>
    /// Indicates whether the argument provided is a built-in Error instance or not.
    /// </summary>
    abstract isError: error: obj -> bool
    /// <summary>
    /// Every model in a client-side fallback chain failed.
    /// </summary>
    [<EmitConstructor>]
    abstract Create: attempts: FallbackAttempt[] * ?message: string -> WorkersAIFallbackError
